# Remove YAML frontmatter from content if present
# @param lines character vector of lines
# @return Lines with frontmatter removed, or all lines if no frontmatter
remove_yaml_frontmatter <- function(lines) {
  if (length(lines) == 0 || lines[1] != "---") {
    return(lines)
  }

  yaml_end_indices <- which(lines == "---")
  if (length(yaml_end_indices) < 2) {
    return(lines)
  }

  lines[(yaml_end_indices[2] + 1):length(lines)]
}

